const request = $input.first().json || {};
const headers = request.headers || {};
const body = request.body && typeof request.body === 'object' ? request.body : {};
const expected = String(request.n8n_leme_secret || '');
const received = String(headers['x-leme-n8n-key'] || headers['X-LEME-N8N-KEY'] || '');

const safeEqual = (a, b) => {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};

const required = ['client_name','file_name','caption','pdf_base64','scan_summary'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
const configured = expected && !expected.startsWith('COLE_AQUI_');
const authorized = configured && safeEqual(received, expected) && missing.length === 0;

return [{
  json: {
    ...body,
    grupo_leme: String(request.grupo_leme || ''),
    evolution_instance: String(request.evolution_instance || 'Leme Marketing Médico'),
    _authorized: authorized,
    _auth_error: !configured
      ? 'Configure n8n_leme_secret no nó CONFIGURAÇÃO — EDITE AQUI.'
      : (!safeEqual(received, expected)
          ? 'X-LEME-N8N-KEY inválida.'
          : (missing.length ? 'Payload incompleto: ' + missing.join(', ') : ''))
  }
}];

const j = $input.first().json || {};
const summary = j.scan_summary || {};
const profile = j.profile_snapshot || {};
const competitors = Array.isArray(j.competitors) ? j.competitors.slice(0, 15) : [];

const profileLines = [
  'Nome: ' + (j.client_name || ''),
  'Especialidade: ' + (j.specialty || ''),
  'Cidade: ' + (j.city || ''),
  'Endereço: ' + (j.address || profile.address || ''),
  'Palavra-chave analisada: ' + (j.keyword || ''),
  'Place ID: ' + (j.profile_place_id || profile.place_id || ''),
  'Google Maps: ' + (j.profile_google_maps_url || profile.google_maps_url || ''),
  'Site: ' + (profile.website_url || ''),
  'Categoria principal: ' + (profile.primary_category || ''),
  'Nota: ' + (profile.rating ?? 'não informado'),
  'Quantidade de avaliações: ' + (profile.review_count ?? 'não informado'),
  'Telefone: ' + (profile.phone || ''),
  'Fotos retornadas pela API: ' + (profile.photo_count ?? 'não informado'),
  'Resumo editorial: ' + (profile.editorial_summary || '')
].join('\n');

const reviews = Array.isArray(profile.reviews)
  ? profile.reviews.map((r, i) => (i + 1) + '. ' + (r.rating ?? '') + '★ — ' + (r.text || '') + ' (' + (r.relative_time || r.published_at || '') + ')').join('\n')
  : '';

const ranking = competitors.map((c, i) =>
  (i + 1) + '. ' + (c.name || 'Perfil') +
  ' | média ' + (c.averagePosition ?? '—') +
  ' | melhor ' + (c.bestPosition ?? '—') +
  ' | Top 10 ' + (c.top10Percent ?? 0) + '%' +
  (c.isTarget ? ' | CLIENTE' : '')
).join('\n');

const auditPrompt = `AUDITORIA LOCAL RADAR + GOOGLE BUSINESS PROFILE

CLIENTE
${profileLines}

RESULTADO LOCAL RADAR
- Posição média: ${summary.averagePosition ?? '—'}
- Melhor posição: ${summary.bestPosition ?? '—'}
- Pior posição: ${summary.worstPosition ?? '—'}
- Top 3: ${summary.top3Percent ?? 0}%
- Top 10: ${summary.top10Percent ?? 0}%
- Não apareceu: ${summary.notFoundPercent ?? 0}%
- Pontos encontrados: ${summary.foundPoints ?? 0}/${summary.totalPoints ?? 0}

CONCORRENTES DO GRID
${ranking || 'Não informado.'}

AVALIAÇÕES/COMENTÁRIOS DISPONÍVEIS NA API
${reviews || 'Nenhum comentário textual enviado pela API.'}

Sua tarefa é auditar o perfil Google Business deste cliente e propor ações para subir no ranking local.
Use a busca na web. Comece pelo Google Maps/Place ID acima e também pesquise o nome exato + cidade.
Cruze o que encontrar com o relatório de posições e com os concorrentes.

Investigue, quando publicamente verificável:
1. categoria principal e categorias/serviços;
2. nome e consistência do perfil;
3. descrição e informações do negócio;
4. site, telefone, endereço e horários;
5. nota, volume, frequência e temas das avaliações;
6. respostas às avaliações e oportunidades de reputação;
7. fotos: variedade, atualização, qualidade e cobertura visual;
8. publicações/posts recentes;
9. sinais de autoridade local e consistência na web;
10. diferenças práticas entre o cliente e os concorrentes que aparecem acima.

Nunca invente algo que não conseguiu verificar. Para qualquer item indisponível, escreva “não verificado”.
Não recomende avaliações falsas, spam, keyword stuffing no nome, compra de reviews ou qualquer prática que viole as diretrizes do Google.
`;

return [{json:{...j,audit_prompt:auditPrompt}}];

